#include <stdio.h>
#include <string.h>
#include <ctype.h>

/*
 * Reimplementation of the original program's observable behavior.
 * The program computes the Soundex code for the first command‑line argument.
 * If no argument is supplied or the argument is an empty string, it prints
 * "EMPTY" (exactly as the original binary does).
 *
 * Soundex algorithm (as used by the original binary):
 *   1. Keep the first letter (converted to upper case).
 *   2. Encode the remaining letters using the standard Soundex digit mapping:
 *        B, F, P, V           -> 1
 *        C, G, J, K, Q, S, X, Z -> 2
 *        D, T                -> 3
 *        L                   -> 4
 *        M, N                -> 5
 *        R                   -> 6
 *        A, E, I, O, U, Y, H, W -> 0 (ignored)
 *   3. Consecutive identical digits are collapsed (the later one is ignored).
 *   4. H and W are completely ignored – they do not break the collapsing rule.
 *   5. The resulting code consists of the first letter followed by three digits.
 *      If fewer than three digits are produced, the code is padded with '0'.
 *   6. The code is printed as a null‑terminated string via puts().
 */

static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0; /* A, E, I, O, U, Y, H, W and any non‑letter */
    }
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *input = argv[1];
    if (input[0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char code[5];          // 4 characters + terminating NUL
    size_t pos = 0;

    /* first letter, upper‑cased */
    char first = toupper((unsigned char)input[0]);
    code[pos++] = first;

    int prev_digit = soundex_digit(first);
    int digit_count = 0;   // how many digits have been stored after the first letter

    for (size_t i = 1; input[i] != '\0' && digit_count < 3; ++i) {
        char ch = input[i];
        if (!isalpha((unsigned char)ch))
            continue;               // ignore non‑alphabetic characters
        ch = toupper((unsigned char)ch);
        if (ch == 'H' || ch == 'W')
            continue;               // H and W are ignored completely
        int d = soundex_digit(ch);
        if (d == 0) {
            prev_digit = 0;        // reset previous digit on vowels/Y
            continue;
        }
        if (d == prev_digit)
            continue;               // collapse duplicate digits
        code[pos++] = (char)('0' + d);
        ++digit_count;
        prev_digit = d;
    }

    /* pad with zeros if we have fewer than three digits */
    while (digit_count < 3) {
        code[pos++] = '0';
        ++digit_count;
    }
    code[pos] = '\0';

    puts(code);
    return 0;
}
